import fs from "node:fs";
import path from "node:path";

const root = process.cwd();
const read = (file) => fs.readFileSync(path.join(root, file), "utf8");
const write = (file, content) => {
  const target = path.join(root, file);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content);
};
const replaceOne = (file, before, after) => {
  const source = read(file);
  if (!source.includes(before)) throw new Error(`Expected snippet not found in ${file}: ${before.slice(0, 120)}`);
  write(file, source.replace(before, after));
};
const replaceRegex = (file, pattern, after) => {
  const source = read(file);
  const match = source.match(pattern);
  if (!match) throw new Error(`Expected pattern not found in ${file}: ${pattern}`);
  write(file, source.replace(pattern, after));
};

const migrationPath = "supabase/migrations/20261002142000_hpo_activity_taxonomy_and_recap_workflow.sql";
if (!fs.existsSync(path.join(root, migrationPath))) {
  write(
    migrationPath,
    `-- HPO Activity: canonical activity taxonomy + next-day recap workflow.\n\nalter table public.hpo_interactions\n  alter column account_id drop not null,\n  add column if not exists activity_type text,\n  add column if not exists activity_title text,\n  add column if not exists meeting_id uuid references public.meetings(id) on delete set null;\n\ndo $$\nbegin\n  if not exists (\n    select 1 from pg_constraint\n    where conname = 'hpo_interactions_activity_type_check'\n      and conrelid = 'public.hpo_interactions'::regclass\n  ) then\n    alter table public.hpo_interactions\n      add constraint hpo_interactions_activity_type_check\n      check (activity_type is null or activity_type in ('office_visit','lunch','dinner','event'));\n  end if;\nend $$;\n\ncreate index if not exists hpo_interactions_user_activity_time_idx\n  on public.hpo_interactions(user_id, activity_type, occurred_at desc)\n  where activity_type is not null;\ncreate index if not exists hpo_interactions_user_meeting_idx\n  on public.hpo_interactions(user_id, meeting_id)\n  where meeting_id is not null;\n\ncreate or replace function public.classify_hpo_interaction_activity()\nreturns trigger\nlanguage plpgsql\nset search_path to 'public'\nas $function$\ndeclare\n  raw_type text;\nbegin\n  raw_type := lower(coalesce(nullif(new.activity_type,''), nullif(new.interaction_type,''), ''));\n  new.activity_type := case\n    when raw_type in ('visit','office_visit','office visit') then 'office_visit'\n    when raw_type = 'lunch' then 'lunch'\n    when raw_type = 'dinner' then 'dinner'\n    when raw_type in ('event','networking_event','networking event') then 'event'\n    else null\n  end;\n  if new.activity_title is null and new.metadata ? 'activity_title' then\n    new.activity_title := nullif(trim(new.metadata->>'activity_title'),'');\n  end if;\n  return new;\nend\n$function$;\n\ndrop trigger if exists hpo_interactions_classify_activity on public.hpo_interactions;\ncreate trigger hpo_interactions_classify_activity\nbefore insert or update of interaction_type, activity_type, activity_title, metadata\non public.hpo_interactions\nfor each row execute function public.classify_hpo_interaction_activity();\n\nupdate public.hpo_interactions\nset activity_type = case\n  when lower(interaction_type) in ('visit','office_visit','office visit') then 'office_visit'\n  when lower(interaction_type) = 'lunch' then 'lunch'\n  when lower(interaction_type) = 'dinner' then 'dinner'\n  when lower(interaction_type) in ('event','networking_event','networking event') then 'event'\n  else activity_type\nend\nwhere activity_type is null\n  and lower(interaction_type) in ('visit','office_visit','office visit','lunch','dinner','event','networking_event','networking event');\n\ncreate or replace function public.sync_hpo_activity_recap_workflow()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path to 'public'\nas $function$\ndeclare\n  activity text;\n  activity_label text;\n  tz text;\n  local_activity_date date;\n  remind_at timestamptz;\n  recap_complete boolean;\n  target_url text;\nbegin\n  if tg_op = 'DELETE' then\n    update public.app_notifications\n    set status='cancelled', updated_at=now()\n    where user_id=old.user_id\n      and source_type='hpo_activity_recap'\n      and source_ref=old.id::text\n      and status in ('pending','delivered');\n    return old;\n  end if;\n\n  activity := lower(coalesce(new.metadata->>'hpo_activity_type',''));\n  recap_complete := lower(coalesce(new.metadata->>'hpo_recap_status','')) = 'complete';\n\n  if activity not in ('office_visit','lunch','dinner','event')\n     or coalesce(new.metadata->>'hpo_recap_required','false') <> 'true'\n     or new.meeting_at is null\n     or recap_complete then\n    update public.app_notifications\n    set status='cancelled', updated_at=now()\n    where user_id=new.user_id\n      and source_type='hpo_activity_recap'\n      and source_ref=new.id::text\n      and status in ('pending','delivered');\n    return new;\n  end if;\n\n  select coalesce(nullif(timezone,''),'America/New_York')\n  into tz\n  from public.profiles\n  where user_id=new.user_id\n  limit 1;\n  tz := coalesce(tz,'America/New_York');\n\n  begin\n    local_activity_date := (new.meeting_at at time zone tz)::date;\n  exception when others then\n    tz := 'America/New_York';\n    local_activity_date := (new.meeting_at at time zone tz)::date;\n  end;\n\n  remind_at := ((local_activity_date + 1)::timestamp + time '09:00') at time zone tz;\n  if remind_at <= now() then\n    remind_at := now() + interval '1 minute';\n  end if;\n\n  activity_label := case activity\n    when 'office_visit' then 'Office visit'\n    when 'lunch' then 'Lunch'\n    when 'dinner' then 'Dinner'\n    else 'Event'\n  end;\n  target_url := '/hpo?activity=1&activityMeetingId=' || new.id::text;\n\n  insert into public.app_notifications(\n    user_id,title,body,scheduled_for,status,source_type,source_ref,metadata\n  ) values (\n    new.user_id,\n    'Emery · ' || activity_label || ' recap',\n    'How did “' || coalesce(nullif(new.title,''),activity_label) || '” go? Tell me what happened, who you spoke with, and any follow-up. I’ll save it under HPO Activity → ' || activity_label || '.',\n    remind_at,\n    'pending',\n    'hpo_activity_recap',\n    new.id::text,\n    jsonb_build_object(\n      'workflow','hpo_activity_recap',\n      'meeting_id',new.id::text,\n      'activity_type',activity,\n      'url',target_url\n    )\n  )\n  on conflict (user_id,source_type,source_ref) where source_ref is not null\n  do update set\n    title=excluded.title,\n    body=excluded.body,\n    scheduled_for=excluded.scheduled_for,\n    status='pending',\n    delivered_at=null,\n    read_at=null,\n    metadata=excluded.metadata,\n    updated_at=now();\n\n  return new;\nend\n$function$;\n\ndrop trigger if exists meetings_hpo_activity_recap_workflow on public.meetings;\ncreate trigger meetings_hpo_activity_recap_workflow\nafter insert or update or delete on public.meetings\nfor each row execute function public.sync_hpo_activity_recap_workflow();\n\nrevoke execute on function public.sync_hpo_activity_recap_workflow() from public, anon, authenticated;\n\ncreate or replace function public.emery_action_create_event(\n  p_user_id uuid,\n  p_title text,\n  p_start_at timestamptz,\n  p_end_at timestamptz default null,\n  p_participants jsonb default '[]'::jsonb,\n  p_event_type text default 'event',\n  p_source text default 'emery'\n)\nreturns public.meetings\nlanguage plpgsql\nset search_path to 'public'\nas $function$\ndeclare\n  v public.meetings;\n  v_end timestamptz;\n  v_type text;\nbegin\n  if not public.emery_action_authorized(p_user_id) then raise exception 'unauthorized'; end if;\n  if nullif(trim(p_title),'') is null or p_start_at is null then raise exception 'event title and start required'; end if;\n  v_end := coalesce(p_end_at, p_start_at + interval '1 hour');\n  if v_end <= p_start_at then raise exception 'event end must be after start'; end if;\n  v_type := case when p_event_type in ('lunch','dinner','meeting','appointment','event') then p_event_type else 'event' end;\n  insert into public.meetings(user_id,title,meeting_at,end_at,participants,metadata)\n  values (\n    p_user_id, trim(p_title), p_start_at, v_end, coalesce(p_participants,'[]'::jsonb),\n    jsonb_build_object('source_type',p_source,'source',p_source,'event_type',v_type,'calendar',true)\n  )\n  returning * into v;\n  return v;\nend\n$function$;\n`,
  );
}

const activityControllerPath = "src/lib/hpo-activity-controller.ts";
if (!fs.existsSync(path.join(root, activityControllerPath))) {
  write(
    activityControllerPath,
    `/* eslint-disable @typescript-eslint/no-explicit-any */\nimport { MODEL_POLICY } from "@/lib/model-policy";\nimport {\n  beginExecution,\n  clarifyExecution,\n  completeExecution,\n  failExecution,\n} from "@/lib/execution-ledger";\n\nexport type HpoActivityType = "office_visit" | "lunch" | "dinner" | "event";\nexport type HpoActivityResult = {\n  recognized: boolean;\n  performed: boolean;\n  needsClarification: boolean;\n  question: string | null;\n  action: "none" | "schedule_activity" | "log_activity";\n  activityType: HpoActivityType | null;\n  activityTitle: string | null;\n  meetingId: string | null;\n  accountId: string | null;\n  accountName: string | null;\n  recordId: string | null;\n  nextAction: string | null;\n  dueAt: string | null;\n  alreadySaved?: boolean;\n  error?: string | null;\n};\n\nfunction responseText(payload: any) {\n  if (typeof payload?.output_text === "string") return payload.output_text.trim();\n  return (payload?.output ?? [])\n    .flatMap((item: any) => (Array.isArray(item?.content) ? item.content : []))\n    .filter((item: any) => item?.type === "output_text")\n    .map((item: any) => item?.text ?? "")\n    .join("")\n    .trim();\n}\nfunction object(value: unknown): Record<string, unknown> {\n  return value && typeof value === "object" && !Array.isArray(value)\n    ? (value as Record<string, unknown>)\n    : {};\n}\nfunction isoOrNull(value: unknown) {\n  if (typeof value !== "string" || !value.trim()) return null;\n  const date = new Date(value);\n  return Number.isNaN(date.getTime()) ? null : date.toISOString();\n}\nfunction emptyResult(): HpoActivityResult {\n  return {\n    recognized: false, performed: false, needsClarification: false, question: null,\n    action: "none", activityType: null, activityTitle: null, meetingId: null,\n    accountId: null, accountName: null, recordId: null, nextAction: null, dueAt: null,\n  };\n}\nfunction label(type: HpoActivityType) {\n  return ({ office_visit: "Office visit", lunch: "Lunch", dinner: "Dinner", event: "Event" })[type];\n}\n\nexport async function processHpoActivity(input: {\n  db: any;\n  userId: string;\n  apiKey: string;\n  message: string;\n  recent?: Array<{ role?: string; text?: string; createdAt?: string }>;\n  timezone?: string;\n  sourceMessageId?: string | null;\n  selectedAccountId?: string | null;\n  calendarAction?: any;\n}): Promise<HpoActivityResult> {\n  const { db, userId, apiKey, message } = input;\n  if (!message.trim()) return emptyResult();\n  const timezone = input.timezone ?? "America/New_York";\n  const now = Date.now();\n  const from = new Date(now - 21 * 24 * 60 * 60 * 1000).toISOString();\n  const to = new Date(now + 120 * 24 * 60 * 60 * 1000).toISOString();\n\n  const [accountsResult, meetingsResult] = await Promise.all([\n    db.from("hpo_accounts")\n      .select("id,name,account_type,specialty,city,status")\n      .eq("user_id", userId)\n      .eq("status", "active")\n      .order("priority", { ascending: false })\n      .limit(180),\n    db.from("meetings")\n      .select("id,title,meeting_at,end_at,participants,metadata")\n      .eq("user_id", userId)\n      .gte("meeting_at", from)\n      .lte("meeting_at", to)\n      .order("meeting_at", { ascending: false })\n      .limit(120),\n  ]);\n  if (accountsResult.error) throw accountsResult.error;\n  if (meetingsResult.error) throw meetingsResult.error;\n  const accounts = accountsResult.data ?? [];\n  const meetings = meetingsResult.data ?? [];\n  const justCreatedIds = (input.calendarAction?.items ?? [])\n    .filter((item: any) => item?.performed && item?.action === "create_event" && item?.recordId)\n    .map((item: any) => String(item.recordId));\n\n  const localNow = new Intl.DateTimeFormat("en-US", {\n    timeZone: timezone, dateStyle: "full", timeStyle: "long",\n  }).format(new Date());\n  const context = JSON.stringify({\n    selected_account_id: input.selectedAccountId ?? null,\n    just_created_calendar_event_ids: justCreatedIds,\n    accounts: accounts.map((row: any) => ({ id: row.id, name: row.name, account_type: row.account_type, specialty: row.specialty, city: row.city })),\n    calendar_events: meetings.map((row: any) => ({\n      id: row.id, title: row.title, meeting_at: row.meeting_at, end_at: row.end_at, metadata: row.metadata,\n    })),\n    recent_conversation: (input.recent ?? []).slice(-10),\n  }).slice(0, 22000);\n\n  const response = await fetch("https://api.openai.com/v1/responses", {\n    method: "POST",\n    headers: { Authorization: \`Bearer \${apiKey}\`, "Content-Type": "application/json" },\n    body: JSON.stringify({\n      model: MODEL_POLICY.action,\n      input: [\n        { role: "system", content: \`You are Emery's canonical HPO Activity controller. HPO Activity is a professional CRM timeline with exactly four activity types:\n\n1. office_visit — a routine in-person relationship/marketing visit to an office. Route stops and field visit notes belong here.\n2. lunch — a business lunch with a doctor, attorney, medical provider, referral partner, office, or professional contact, whether at an office or restaurant.\n3. dinner — the same relationship purpose as Lunch, but a dinner/evening meal.\n4. event — a broader networking, industry, relationship, social-business, conference, open-house, or hosted event such as the Paramus MRI Oktoberfest. Do not use Event for routine office visits or meals.\n\nDo not classify calls, texts, emails, or ordinary personal activities into these four types.\n\nA future HPO activity is a Calendar event plus an HPO Activity classification. Use schedule_activity only when Adam clearly asks Emery to put/schedule/add the business activity on his calendar or schedule. The Calendar controller runs before you, so a just-created event id may appear in just_created_calendar_event_ids. Match the exact current event; never invent an id.\n\nUse log_activity when Adam clearly asks to log/save a completed activity OR when he is plainly answering an Emery recap prompt for a pending HPO activity with substantive details. If a completed activity is mentioned but Emery does not yet know what happened, who he spoke with, or any useful outcome, ask one short recap question instead of inventing a summary. For a pending activity from yesterday/recently, if exactly one event clearly fits the user's recap, you may attach it even if the user does not repeat the title.\n\nOffice visits created through the route/stop workflow are normally logged by the route controller; do not duplicate a visit that is already represented in HPO interaction history.\n\nFor schedule_activity, activity_type and meeting_id are required. For log_activity, activity_type and a factual summary are required; meeting_id may be null for a retrospective activity that was never on the Calendar. Lunches, dinners, and events may be accountless if they involved multiple contacts or no exact HPO account. An office_visit should target an exact office/account when possible.\n\nNever store patient names, DOBs, diagnoses, claim/case identifiers, treatment details, or other PHI. Business contact names are allowed.\n\nResolve relative dates from CURRENT LOCAL TIME. Do not invent a follow-up date or time. Return strict JSON only.\` },\n        { role: "system", content: \`CURRENT LOCAL TIME: \${localNow} (\${timezone})\` },\n        { role: "system", content: \`CURRENT HPO ACTIVITY CONTEXT:\n\${context}\` },\n        { role: "user", content: [{ type: "input_text", text: message }] },\n      ],\n      text: { format: { type: "json_schema", name: "emery_hpo_activity", strict: true, schema: {\n        type: "object", additionalProperties: false, properties: {\n          recognized: { type: "boolean" },\n          action: { type: "string", enum: ["none","schedule_activity","log_activity"] },\n          needs_clarification: { type: "boolean" },\n          clarification_question: { type: ["string","null"] },\n          activity_type: { type: ["string","null"], enum: ["office_visit","lunch","dinner","event",null] },\n          activity_title: { type: ["string","null"] },\n          meeting_id: { type: ["string","null"] },\n          target_account_id: { type: ["string","null"] },\n          occurred_at: { type: ["string","null"] },\n          summary: { type: "string" },\n          outcome: { type: "string" },\n          relationship_signal: { type: "string" },\n          next_action: { type: "string" },\n          due_at: { type: ["string","null"] },\n          contains_phi: { type: "boolean" }\n        },\n        required: ["recognized","action","needs_clarification","clarification_question","activity_type","activity_title","meeting_id","target_account_id","occurred_at","summary","outcome","relationship_signal","next_action","due_at","contains_phi"]\n      } } },\n    }),\n  });\n  if (!response.ok) throw new Error(\`HPO Activity model failed: \${response.status}\`);\n  const parsed = JSON.parse(responseText(await response.json()) || "{}");\n  if (!parsed.recognized || !["schedule_activity","log_activity"].includes(parsed.action)) return emptyResult();\n  const action = parsed.action as "schedule_activity" | "log_activity";\n  const activityType = parsed.activity_type as HpoActivityType | null;\n\n  const execution = await beginExecution({\n    db, userId, domain: "hpo", action: \`hpo.activity.\${action}\`,\n    sourceMessageId: input.sourceMessageId ?? null,\n    idempotencyKey: input.sourceMessageId ? \`message:\${input.sourceMessageId}:hpo-activity:\${action}\` : null,\n    targetType: action === "schedule_activity" ? "meeting" : "hpo_interaction",\n    targetId: parsed.meeting_id ?? null,\n    requestPayload: { message, activityType, activityTitle: parsed.activity_title ?? null, meetingId: parsed.meeting_id ?? null, targetAccountId: parsed.target_account_id ?? null },\n  });\n  if (execution.reused && execution.resultPayload["hpoActivityResult"]) {\n    return execution.resultPayload["hpoActivityResult"] as HpoActivityResult;\n  }\n\n  const clarify = async (question: string): Promise<HpoActivityResult> => {\n    const result: HpoActivityResult = {\n      recognized: true, performed: false, needsClarification: true, question, action,\n      activityType, activityTitle: parsed.activity_title ?? null, meetingId: parsed.meeting_id ?? null,\n      accountId: parsed.target_account_id ?? null, accountName: null, recordId: null,\n      nextAction: parsed.next_action || null, dueAt: isoOrNull(parsed.due_at),\n    };\n    await clarifyExecution({ db, userId, runId: execution.id, question, resultPayload: { hpoActivityResult: result as unknown as Record<string, unknown> } });\n    return result;\n  };\n\n  if (parsed.contains_phi) return clarify("Tell me only the non-patient relationship details from that activity so I can save it safely.");\n  if (parsed.needs_clarification) return clarify(String(parsed.clarification_question || "What happened at that activity, who did you speak with, and is there any follow-up?"));\n  if (!activityType) return clarify("Should I file this as an Office visit, Lunch, Dinner, or Event?");\n\n  let meetingId = typeof parsed.meeting_id === "string" ? parsed.meeting_id : null;\n  if (!meetingId && justCreatedIds.length === 1 && action === "schedule_activity") meetingId = justCreatedIds[0];\n  let meeting = meetingId ? meetings.find((row: any) => row.id === meetingId) ?? null : null;\n  if (meetingId && !meeting) {\n    const exact = await db.from("meetings").select("id,title,meeting_at,end_at,participants,metadata").eq("user_id", userId).eq("id", meetingId).maybeSingle();\n    if (exact.error) throw exact.error;\n    meeting = exact.data ?? null;\n  }\n  const account = accounts.find((row: any) => row.id === parsed.target_account_id) ?? null;\n\n  if (action === "schedule_activity") {\n    if (!meeting) return clarify("What date and time should I put this HPO activity on your calendar?");\n    const currentMeta = object(meeting.metadata);\n    const inferredAccountId = account?.id ?? (typeof currentMeta["account_id"] === "string" ? String(currentMeta["account_id"]) : null);\n    const activityTitle = String(parsed.activity_title || meeting.title || label(activityType)).trim();\n    const nextMeta = {\n      ...currentMeta,\n      domain: "hpo",\n      hpo: true,\n      hpo_activity_type: activityType,\n      hpo_activity_title: activityTitle,\n      hpo_account_id: inferredAccountId,\n      hpo_recap_required: true,\n      hpo_recap_status: "pending",\n      hpo_activity_source: "emery",\n      hpo_activity_source_message_id: input.sourceMessageId ?? null,\n    };\n    const updated = await db.from("meetings").update({ metadata: nextMeta }).eq("user_id", userId).eq("id", meeting.id).select("id,title").single();\n    if (updated.error || !updated.data) {\n      await failExecution({ db, userId, runId: execution.id, errorCode: "hpo_activity_schedule_failed", errorMessage: String(updated.error?.message ?? updated.error ?? "Activity classification failed"), retryable: true });\n      throw updated.error ?? new Error("HPO Activity classification failed");\n    }\n    const result: HpoActivityResult = {\n      recognized: true, performed: true, needsClarification: false, question: null, action,\n      activityType, activityTitle, meetingId: meeting.id, accountId: inferredAccountId,\n      accountName: account?.name ?? null, recordId: meeting.id, nextAction: null, dueAt: null,\n    };\n    await completeExecution({ db, userId, runId: execution.id, resultPayload: { hpoActivityResult: result as unknown as Record<string, unknown> }, targetType: "meeting", targetId: meeting.id });\n    return result;\n  }\n\n  const summary = String(parsed.summary ?? "").trim();\n  if (!summary) {\n    const title = String(parsed.activity_title || meeting?.title || label(activityType));\n    return clarify(\`How did \${title} go? Who did you speak with, what happened, and is there any follow-up I should save?\`);\n  }\n  if (meetingId) {\n    const existing = await db.from("hpo_interactions").select("id,account_id,activity_type,activity_title,next_action,next_action_due_at").eq("user_id", userId).eq("meeting_id", meetingId).limit(1).maybeSingle();\n    if (existing.error) throw existing.error;\n    if (existing.data) {\n      const result: HpoActivityResult = {\n        recognized: true, performed: true, needsClarification: false, question: null, action,\n        activityType: (existing.data.activity_type ?? activityType) as HpoActivityType,\n        activityTitle: existing.data.activity_title ?? parsed.activity_title ?? meeting?.title ?? null,\n        meetingId, accountId: existing.data.account_id ?? null, accountName: account?.name ?? null,\n        recordId: existing.data.id, nextAction: existing.data.next_action ?? null,\n        dueAt: existing.data.next_action_due_at ?? null, alreadySaved: true,\n      };\n      await completeExecution({ db, userId, runId: execution.id, resultPayload: { hpoActivityResult: result as unknown as Record<string, unknown> }, targetType: "hpo_interaction", targetId: existing.data.id });\n      return result;\n    }\n  }\n\n  const meetingMeta = object(meeting?.metadata);\n  const meetingAccountId = typeof meetingMeta["hpo_account_id"] === "string"\n    ? String(meetingMeta["hpo_account_id"])\n    : typeof meetingMeta["account_id"] === "string"\n      ? String(meetingMeta["account_id"])\n      : null;\n  const resolvedAccount = account ?? accounts.find((row: any) => row.id === meetingAccountId) ?? null;\n  if (activityType === "office_visit" && !resolvedAccount && !meeting) {\n    return clarify("Which office should I attach that office visit to?");\n  }\n  const occurredAt = isoOrNull(parsed.occurred_at) ?? meeting?.meeting_at ?? new Date().toISOString();\n  const activityTitle = String(parsed.activity_title || meeting?.title || (resolvedAccount ? \`\${label(activityType)} · \${resolvedAccount.name}\` : label(activityType))).trim();\n  const dueAt = isoOrNull(parsed.due_at);\n  const inserted = await db.from("hpo_interactions").insert({\n    user_id: userId,\n    account_id: resolvedAccount?.id ?? null,\n    interaction_type: activityType === "office_visit" ? "visit" : activityType,\n    activity_type: activityType,\n    activity_title: activityTitle,\n    meeting_id: meeting?.id ?? null,\n    occurred_at: occurredAt,\n    summary,\n    outcome: String(parsed.outcome || "").trim() || null,\n    relationship_signal: String(parsed.relationship_signal || "").trim() || null,\n    next_action: String(parsed.next_action || "").trim() || null,\n    next_action_due_at: dueAt,\n    source_type: "emery_activity",\n    source_ref: input.sourceMessageId ?? null,\n    metadata: { non_phi: true, structured_activity: true, source_message_id: input.sourceMessageId ?? null },\n  }).select("id").single();\n  if (inserted.error || !inserted.data) {\n    await failExecution({ db, userId, runId: execution.id, errorCode: "hpo_activity_log_failed", errorMessage: String(inserted.error?.message ?? inserted.error ?? "Activity write failed"), retryable: true });\n    throw inserted.error ?? new Error("HPO Activity write failed");\n  }\n\n  if (resolvedAccount) {\n    const accountUpdate: Record<string, unknown> = { last_touch_at: occurredAt, updated_at: new Date().toISOString() };\n    if (String(parsed.next_action || "").trim()) accountUpdate["next_action"] = String(parsed.next_action).trim();\n    if (dueAt) accountUpdate["next_action_due_at"] = dueAt;\n    const updated = await db.from("hpo_accounts").update(accountUpdate).eq("user_id", userId).eq("id", resolvedAccount.id);\n    if (updated.error) throw updated.error;\n  }\n\n  if (meeting) {\n    const completedMeta = {\n      ...meetingMeta,\n      domain: "hpo", hpo: true, hpo_activity_type: activityType, hpo_activity_title: activityTitle,\n      hpo_account_id: resolvedAccount?.id ?? meetingAccountId, hpo_recap_required: true,\n      hpo_recap_status: "complete", hpo_recap_completed_at: new Date().toISOString(),\n      hpo_interaction_id: inserted.data.id,\n    };\n    const completed = await db.from("meetings").update({ metadata: completedMeta }).eq("user_id", userId).eq("id", meeting.id);\n    if (completed.error) throw completed.error;\n  }\n\n  const result: HpoActivityResult = {\n    recognized: true, performed: true, needsClarification: false, question: null, action, activityType,\n    activityTitle, meetingId: meeting?.id ?? null, accountId: resolvedAccount?.id ?? null,\n    accountName: resolvedAccount?.name ?? null, recordId: inserted.data.id,\n    nextAction: String(parsed.next_action || "").trim() || null, dueAt,\n  };\n  await completeExecution({ db, userId, runId: execution.id, resultPayload: { hpoActivityResult: result as unknown as Record<string, unknown> }, targetType: "hpo_interaction", targetId: inserted.data.id });\n  return result;\n}\n`,
  );
}

