write(
  "scripts/validate-hpo-activity-workflow.mjs",
  `import fs from "node:fs";\nconst read = (file) => fs.readFileSync(file, "utf8");\nconst expect = (condition, message) => { if (!condition) throw new Error(message); };\nconst migration = read("supabase/migrations/20261002142000_hpo_activity_taxonomy_and_recap_workflow.sql");\nconst controller = read("src/lib/hpo-activity-controller.ts");\nconst view = read("src/components/HpoActivityView.tsx");\nconst emery = read("src/lib/emery.functions.ts");\nconst workspace = read("src/lib/hpo-workspace.functions.ts");\nfor (const type of ["office_visit","lunch","dinner","event"]) {\n  expect(migration.includes(type), \`migration missing \${type}\`);\n  expect(controller.includes(type), \`controller missing \${type}\`);\n  expect(view.includes(type), \`Activity view missing \${type}\`);\n}\nexpect(migration.includes("hpo_activity_recap"), "next-day HPO recap workflow missing");\nexpect(migration.includes("time '09:00'"), "next-day recap time missing");\nexpect(emery.includes("processHpoActivity"), "regular Emery is not connected to HPO Activity");\nexpect(workspace.includes("activity_type,activity_title,meeting_id"), "HPO workspace does not load structured activity fields");\nexpect(view.includes("Office visits") && view.includes("Lunches") && view.includes("Dinners") && view.includes("Events"), "Activity dropdown is incomplete");\nconsole.log("HPO Activity workflow validation passed");\n`,
);

replaceOne(
  "package.json",
  '    "validate:hpo-account": "node scripts/validate-hpo-account-experience.mjs"',
  '    "validate:hpo-account": "node scripts/validate-hpo-account-experience.mjs",\n    "validate:hpo-activity": "node scripts/validate-hpo-activity-workflow.mjs"',
);

// Keep push notification deep links when app_notifications metadata supplies one.
const pushSourcePath = "supabase/functions/emery-push-dispatch/index.ts";
write(
  pushSourcePath,
  `import "jsr:@supabase/functions-js/edge-runtime.d.ts";\nimport { createClient } from "npm:@supabase/supabase-js@2";\nimport webpush from "npm:web-push@3.6.7";\n\nfunction json(body: unknown, status = 200) {\n  return new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" } });\n}\nDeno.serve(async (req: Request) => {\n  try {\n    if (req.method !== "POST") return json({ error: "POST required" }, 405);\n    const url = Deno.env.get("SUPABASE_URL");\n    const serviceRole = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");\n    if (!url || !serviceRole) return json({ error: "Server configuration missing" }, 500);\n    const db = createClient(url, serviceRole, { auth: { persistSession: false, autoRefreshToken: false } });\n    const [{ data: vapidPublic, error: publicError }, { data: vapidPrivate, error: privateError }] = await Promise.all([\n      db.rpc("get_internal_secret", { p_name: "emery_vapid_public" }),\n      db.rpc("get_internal_secret", { p_name: "emery_vapid_private" }),\n    ]);\n    if (publicError || privateError || !vapidPublic || !vapidPrivate) return json({ error: "Push credentials missing" }, 500);\n    webpush.setVapidDetails("mailto:adam.emailassistant@gmail.com", String(vapidPublic), String(vapidPrivate));\n    const suppliedCronKey = req.headers.get("x-emery-cron-key") ?? "";\n    if (!suppliedCronKey) return json({ error: "Unauthorized" }, 401);\n    const { data: tokenValid, error: tokenError } = await db.rpc("validate_internal_cron_token", { p_name: "emery_push_dispatch", p_token: suppliedCronKey });\n    if (tokenError || tokenValid !== true) return json({ error: "Unauthorized" }, 401);\n    const now = new Date().toISOString();\n    const { data: notifications, error } = await db.from("app_notifications").select("id,user_id,title,body,scheduled_for,status,source_type,source_ref,metadata").eq("status", "pending").lte("scheduled_for", now).order("scheduled_for", { ascending: true }).limit(50);\n    if (error) throw error;\n    let delivered = 0;\n    let attempted = 0;\n    for (const notification of notifications ?? []) {\n      const { data: subscriptions, error: subError } = await db.from("push_subscriptions").select("id,endpoint,p256dh,auth").eq("user_id", notification.user_id);\n      if (subError) { console.error("Push subscription query failed", subError); continue; }\n      let sentForNotification = false;\n      const metadata = notification.metadata && typeof notification.metadata === "object" && !Array.isArray(notification.metadata) ? notification.metadata as Record<string, unknown> : {};\n      const targetUrl = typeof metadata.url === "string" && metadata.url.startsWith("/") ? metadata.url : "/calendar";\n      for (const subscription of subscriptions ?? []) {\n        attempted += 1;\n        try {\n          await webpush.sendNotification(\n            { endpoint: subscription.endpoint, keys: { p256dh: subscription.p256dh, auth: subscription.auth } },\n            JSON.stringify({ title: notification.title, body: notification.body || "You have a reminder from Emery.", url: targetUrl, notificationId: notification.id, sourceType: notification.source_type }),\n            { TTL: 60 * 60 * 24 },\n          );\n          sentForNotification = true;\n        } catch (pushError: any) {\n          const statusCode = Number(pushError?.statusCode ?? 0);\n          console.error("Push delivery failed", statusCode, pushError?.message ?? pushError);\n          if (statusCode === 404 || statusCode === 410) await db.from("push_subscriptions").delete().eq("id", subscription.id);\n        }\n      }\n      if (sentForNotification) {\n        delivered += 1;\n        await db.from("app_notifications").update({ status: "delivered", delivered_at: new Date().toISOString(), updated_at: new Date().toISOString() }).eq("id", notification.id).eq("status", "pending");\n      }\n    }\n    return json({ ok: true, due: notifications?.length ?? 0, attempted, delivered });\n  } catch (error) {\n    console.error("Emery push dispatch failed", error);\n    return json({ error: "Push dispatch failed" }, 500);\n  }\n});\n`,
);

console.log("HPO Activity upgrade patch applied to working tree.");
